The final code
function parallel(funcs){
  // your code here
  return function (callback) {
    if(funcs.length === 0) {
      callback(undefined, []);
      return;
    }

    const results = [];
    let completed = 0;
    let hasError = false;

    funcs.forEach((func, index) => {
      func((error, result) => {
        if(hasError) return;

        if(error) {
          hasError = true;
          callback(error, undefined);
          return;
        }
        results[index] = result;
        completed++;

        if (completed === funcs.length) {
          callback(undefined, results)
        }
      })
    })
  }
}

That's all folks!

